let activeCaseId = null;
// Per-case busy tracking — enables simultaneous AI chats across cases
const busyMap = new Map();       // caseId -> true/false
const streamControllers = new Map(); // caseId -> AbortController
const streamingElements = new Map(); // caseId -> live aib DOM element currently being streamed into

// Keep-alive: prevent browser from throttling the side panel when user switches tabs.
// Without this, the fetch/stream loop is paused mid-response when the panel is hidden.
(function installVisibilityKeepAlive() {
    let keepAliveInterval = null;
    document.addEventListener('visibilitychange', () => {
        if (document.hidden) {
            // Start a no-op interval to keep the JS event loop warm while tab is hidden
            if (!keepAliveInterval) {
                keepAliveInterval = setInterval(() => { /* keep-alive ping */ }, 200);
            }
        } else {
            // Tab is visible again — clear the keep-alive and re-scroll to any active stream
            if (keepAliveInterval) {
                clearInterval(keepAliveInterval);
                keepAliveInterval = null;
            }
            // Re-scroll to the live streaming element so user can see it resumed
            if (activeCaseId) {
                const liveEl = streamingElements.get(activeCaseId);
                const chat = document.getElementById('chatMsgs');
                if (liveEl && chat && chat.contains(liveEl)) {
                    liveEl.scrollIntoView({ behavior: 'smooth', block: 'end' });
                }
            }
        }
    });
})();
/* ---------------------------------------------------------------------------
 * POWER & RESOURCE GOVERNOR BRIDGE
 * ---------------------------------------------------------------------------
 * The governor itself lives in power.js and is loaded BEFORE this file. Every
 * call site below goes through this bridge rather than touching window.SotiPower
 * directly, for one reason: the app must still work if power.js is missing,
 * blocked, or fails to construct. The fallback knobs are exactly the constants
 * this file used before the governor existed, so a missing power.js costs
 * adaptivity — not correctness.
 *
 * Read `Power.knobs` FRESH at each decision point. It is a live computation of
 * the current pressure level; caching it is how you end up running an idle
 * throttle through an analysis that has already gone critical.
 * ------------------------------------------------------------------------- */
const Power = (function () {
    const G = (typeof window !== 'undefined' && window.SotiPower) ? window.SotiPower : null;

    // Pre-governor behaviour, preserved verbatim as the fallback.
    const STATIC_KNOBS = Object.freeze({
        yieldEveryMs: 20,
        chunkLines: 2000,
        promptScale: 1,
        answerScale: 1,
        maxOcrWorkers: 2,
        maxResidentLogBytes: Infinity,
        maxHydratedCases: Infinity,
        prewarmKb: true,
        level: 'ok',
        tier: 'unknown'
    });

    const noop = () => {};
    const noopHandle = {
        entry: {},
        firstToken: noop,
        touch: noop,
        end: () => ({})
    };

    return {
        available: !!G,
        governor: G,
        get knobs() {
            if (!G) return STATIC_KNOBS;
            try { return G.knobs; } catch (e) { return STATIC_KNOBS; }
        },
        get level() { return G ? G.level : 'ok'; },
        get tier() { return G ? G.tier : 'unknown'; },
        get budgetMB() { return G ? G.budgetMB : 0; },
        snapshot() { return G ? G.snapshot() : null; },
        profile() { return G ? G.profile : null; },
        markActive(ms) { if (G) { try { G.markActive(ms); } catch (e) {} } },
        canAllocate(bytes) {
            if (!G) return { ok: true, reason: 'no-governor' };
            try { return G.canAllocate(bytes); } catch (e) { return { ok: true, reason: 'error' }; }
        },
        registerReclaimer(spec) {
            if (!G) return noop;
            try { return G.registerReclaimer(spec); } catch (e) { return noop; }
        },
        onChange(fn) {
            if (!G) return noop;
            try { return G.onChange(fn); } catch (e) { return noop; }
        },
        perf: {
            start(kind, meta) {
                if (!G) return noopHandle;
                try { return G.perf.start(kind, meta); } catch (e) { return noopHandle; }
            },
            mark(kind, data) {
                if (!G) return null;
                try { return G.perf.mark(kind, data); } catch (e) { return null; }
            },
            entries() { return G ? G.perf.entries() : []; },
            summary() { return G ? G.perf.summary() : []; },
            clear() { if (G) { try { G.perf.clear(); } catch (e) {} } }
        }
    };
})();

let RELEASE_NOTES_CONTENT = "";
let PULSE_SEARCH_RESULTS = "";
let DOCS_SEARCH_RESULTS = "";
let RESEARCHED_ARTICLE_CONTENT = "";
let VERSIONS = [], AGENT_VERSIONS = [], IDENTITY_VERSIONS = [];

// ---- MCMR CITATION CONTROL (a cited MCMR must be RIGHT, or not cited at all) ----
// An MCMR code is a promise to the customer that their exact defect is fixed in a named
// build, so a near-miss is worse than silence: a case summary once cited "MCMR-35305"
// (device agents disconnecting/reconnecting) as the reference for an internal-server-error-
// after-upgrade case, purely because that code sat inside a wholesale release-notes dump
// the model was handed. Two mechanisms replace that guesswork:
//   • VERIFIED_MCMR_ENTRIES — only release-notes lines that pass a STRICT deterministic
//     symptom match against this case reach the prompt, and each one is recorded here with
//     the version it shipped in. This is the allow-list the model is told to cite from.
//   • MCMR_CITATION_MODE — 'strict' for case/troubleshooting turns (allow-list only),
//     'open' only when the agent explicitly asked to see release notes / resolved issues
//     (then the whole listing is legitimately quotable, because the listing IS the answer).
// enforceMcmrCitations() then deletes any MCMR the model produces outside that set, so a
// wrong code can never reach the customer even if the model ignores the instruction.
let VERIFIED_MCMR_ENTRIES = [];      // [{ code, version, product, line }]
let MCMR_CITATION_MODE = 'strict';   // 'strict' | 'open'
function resetMcmrCitationState(mode = 'strict') {
    VERIFIED_MCMR_ENTRIES = [];
    MCMR_CITATION_MODE = mode;
}
const PULSE_ORIGIN = 'https://pulse.soti.net';
const DOCS_ORIGIN = 'https://docs.soti.net';
let PULSE_RELEASE_NOTE_CATALOG = {};

function isChromeExtension() {
    return typeof chrome !== 'undefined' && !!(chrome.runtime && chrome.runtime.id);
}

function isStandalonePage() {
    return !isChromeExtension();
}

function md(t) {
    if (!t) return "";
    // SECURITY (defence-in-depth on top of the CSP): md() output goes to innerHTML, and its
    // input can include untrusted text (a scraped case/email, OCR text, or the local model's
    // echo of that content). HTML-escape the input BEFORE applying markdown so no injected tag
    // (<img src="http…"> beacon, <script>, <iframe>, event handler) can ever render — the CSP
    // already blocks execution/exfiltration, this closes the gap if the CSP is ever relaxed.
    // The app's OWN inline previews (self-contained base64 data: images for attached
    // screenshots) and its OWN static UI markup (the "thinking…" loading spinner, injected as
    // literal HTML while a response streams) are the only trusted HTML this function ever
    // receives — set them aside so escaping doesn't destroy them, then restore after the
    // markdown pass. Nothing here is templated with user/case/AI-controlled data.
    const _safeImgs = [];
    t = String(t)
        .replace(/<img\s+src="data:image\/(?:png|jpe?g|gif|webp|bmp);base64,[^"]*"[^>]*>/gi, (m) => {
            _safeImgs.push(m);
            return `%%SAFEIMG${_safeImgs.length - 1}%%`;
        })
        .replace(/<div class="thinking-dot"><\/div>/g, (m) => {
            _safeImgs.push(m);
            return `%%SAFEIMG${_safeImgs.length - 1}%%`;
        });
    t = t.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
    let html = t.trim()
        // 1. Fix token-mashing where AI forgets spaces around bold tags (e.g. the**Android**tab)
        .replace(/([A-Za-z0-9.,])\*\*/g, '$1 **')
        .replace(/\*\*([A-Za-z0-9])/g, '** $1')
        
        // 2. Force newlines before markdown headings (###) that got squashed inline (e.g. Procedure:### Method)
        .replace(/([^\n])\s*(#{1,3})\s/g, '$1\n\n$2 ')
        
        // 3. Force newlines before numbered lists that got squashed (e.g. UUID 1. Log into)
        .replace(/([a-zA-Z:).*\"])\s*(\d+\.\s+[A-Z])/g, (match, p1, p2, offset, string) => {
            let before = string.slice(Math.max(0, offset - 15), offset);
            if (/(Step|Method)\s*$/i.test(before)) return match;
            // "...regression in MobiControl 2026.1.1. Checking with dev" — the trailing "1." is
            // the last octet of a dotted VERSION NUMBER ending a sentence, not the start of a
            // numbered list. Splitting there turned the rest of the sentence into an <ol> item
            // and swallowed the bullet that followed, tearing chain-timeline entries in half.
            if (p1 === '.' && /\d$/.test(before)) return match;
            return p1 + '\n\n' + p2;
        })
        
        // 4. Force newlines before bullet points that got squashed (e.g. Tips:- Ensure)
        .replace(/([a-zA-Z:.])\s*([•*+-])\s+([A-Z])/g, '$1\n\n$2 $3')
        
        // 5. Force spacing before common inline headers and guide steps (Case-insensitive, safe headers only).
        //    Longer phrases FIRST so "Case Timeline"/"Current Status" win before "Summary" could split them.
        .replace(/(^|\W)(\*\*)?(Time of the meeting|Case Timeline|Current Status|Key Details|Troubleshooting tips|Troubleshooting steps|Troubleshoots done|Next steps|Additional information|Root cause|Resolution|Pre-requisites|Prerequisites|Summary|Step \d+|Method \d+):\s*(\*\*)?/gi, '$1\n\n**$3:** ')

        .replace(/```([\s\S]*?)```/g, '<div style="background:rgba(0,0,0,0.3); padding:12px; border-radius:8px; font-family:monospace; margin:15px 0; border:1px solid rgba(255,255,255,0.1); white-space:pre-wrap; word-break:break-all; font-size:12px">$1</div>')
        // Bold label glued to its text ("**Key Details:**- SOTI") — force the missing space
        .replace(/(\*\*[^\n*]{1,80}:\*\*)(?=\S)/g, '$1 ')
        // Bold/italic are SINGLE-LINE only: the old [\s\S]*? spans let one stray/unbalanced
        // marker pair up with a much later one and bold/italicize entire paragraphs.
        .replace(/\*\*([^\n]+?)\*\*/g, (m, p1) => '<strong>' + p1.trim() + '</strong>')
        .replace(/(^|[\s(])\*([^\s*][^\n*]*?)\*(?=$|[\s).,;:!?])/gm, '$1<em>$2</em>')
        // Headings KEEP their trailing newline: the list rules below are ^-anchored, so a
        // heading that swallowed it left the first bullet of the following list without a line
        // start — it rendered as a literal "- **text**" while every later bullet in the same
        // list rendered correctly. The newline is stripped again after the <br>/gap conversion
        // (see the cleanup below), so no stray gap opens under a heading either.
        .replace(/^[ \t]*###[ \t]*(.*)(\n?)/gim, '<h3 style="margin:22px 0 10px; color:var(--blue); font-weight:700; line-height:1.3">$1</h3>$2')
        .replace(/^[ \t]*##[ \t]*(.*)(\n?)/gim, '<h2 style="margin:28px 0 12px; color:var(--blue); font-weight:700; line-height:1.3">$1</h2>$2')
        .replace(/^[ \t]*#[ \t]*(.*)(\n?)/gim, '<h1 style="margin:35px 0 15px; color:var(--blue); font-weight:700; line-height:1.3">$1</h1>$2')
        .replace(/^\s*---\s*$/gm, '<hr style="border:0; border-top:1px solid var(--border); margin:25px 0">')
        // List lines are converted BEFORE newlines become <br> — the old order ran the
        // ^-anchored list rules on a string that no longer had line starts, so only the
        // FIRST bullet of a list was ever rendered as a bullet. Each rule consumes its
        // trailing newline so the block <div> isn't followed by a stray <br>.
        .replace(/^[ \t]*(\d+\.)[ \t]+(.*)\n?/gim, '<div style="margin-left:10px; margin-bottom:10px; display:flex; align-items:flex-start"><span style="min-width:25px; font-weight:bold; color:var(--blue)">$1</span><span>$2</span></div>')
        .replace(/^[ \t]*[•*+-][ \t]+(.*)\n?/gim, '<div style="margin-left:10px; margin-bottom:10px; display:flex; align-items:flex-start"><span style="min-width:25px; color:var(--blue)">•</span><span>$1</span></div>')
        .replace(/\n\n/g, '<div style="margin-bottom:18px"></div>')
        .replace(/\n/g, '<br>');
        
    // A heading's own margin provides the space below it, so drop the line break / paragraph
    // gap that its (now preserved) trailing newline turned into — otherwise every heading
    // opens a double gap. Done here, AFTER the list rules have used that newline as an anchor.
    html = html.replace(/(<\/h[123]>)(?:<br>|<div style="margin-bottom:18px"><\/div>)+/g, '$1');
    // Any ** still present is a stray/unbalanced marker (all real bold pairs were converted
    // above) — showing literal asterisks reads as broken formatting, so drop them.
    html = html.replace(/\*\*/g, '');
    // Restore the app's own inline image previews that were protected before escaping.
    html = html.replace(/%%SAFEIMG(\d+)%%/g, (m, i) => _safeImgs[+i] || '');
    // Clean up any stray leading/trailing breaks that might have been injected
    return html.replace(/^(<br>|<div style="margin-bottom:18px"><\/div>|\s)+/, '').replace(/(<br>|<div style="margin-bottom:18px"><\/div>|\s)+$/, '');
}

// Strip leaked [EMAIL CHAIN] "Message N" markers from ANY model output. The numbering is
// internal prompt structure; user-facing text must reference emails by author/date. Handles
// parentheticals with any short lead-in ("(Provided in Message 23)", "(see Message 3)",
// "(Message 19)"), inline references ("as noted in Message 4 of 13"), plural lists
// ("Messages 3 and 5"), and bare noun uses ("Message 7 shows..."). "Message" is matched
// case-SENSITIVELY (the markers always capitalize it) so real prose like
// "the error message 404" is never touched.
function stripEmailChainMarkers(text) {
    return String(text)
        .replace(/\s*\(\s*[^()]{0,40}?Messages?\s+\d+[^()]{0,24}?\s*\)/g, "")
        .replace(/\b(?:in|from|per|at)\s+Message\s+\d+(?:\s+of\s+\d+)?\b/g, "in the email chain")
        .replace(/\bMessage\s+\d+\s+of\s+\d+,?\s*/g, "the message ")
        .replace(/\bMessages\s+\d+(?:\s*(?:,|and|&|to|through|[-–])\s*\d+)*\b/g, "earlier emails")
        .replace(/\bMessage\s+\d+\b(?!\s*(?:of|\)))/g, "an email in the chain");
}

// ---------------------------------------------------------------------------
// PROMPT-SCAFFOLD LEAK GUARD
// ---------------------------------------------------------------------------
// Every case-writing prompt is assembled from bracketed ALL-CAPS blocks — [CASE HISTORY],
// [CASE STATE], [LOG ACCESS], [MCMR RULE], [SOTI CHECKS THAT FIT THIS SYMPTOM — …] — that
// exist ONLY inside the prompt. A small local model does not read them as its own briefing:
// it reads them as places the ENGINEER can go, and writes next steps like
//     2. Review the [SOTI CHECKS…]/research blocks for any findings related to version 26.1.0
//     3. Check the [MCMR RULE] block for a matching fix and recommend the upgrade if found
// Both are worse than useless: there is no such block anywhere the engineer can open, and the
// step hands back the exact work the model was asked to do. Deleting the label on its own is
// no fix either — it leaves "Review the /research blocks for any findings".
// So a reference is CLASSIFIED, not merely erased:
//   • a block that names something the engineer knows ([RELEASE NOTES], [CASE HISTORY],
//     [CALL LOG]) is rewritten into plain English and its sentence survives intact;
