// A whole DIRECTIVE BLOCK echoed back at the end of the answer, rather than a reference to one
// inside a sentence. stripPromptScaffold only knows the second shape: it recognises a block by
// its BRACKETS, or unbracketed only when a structural noun follows ("the LOG ACCESS directive").
// A model that copies the block out drops the brackets and keeps the heading — "CASE STATE:",
// "RECURRENCE — the customer reported…" — which matches neither, so the guard ran and changed
// nothing. Observed on 3 of 5 drafted emails, appended UNDER "Technical Support, SOTI" in output
// labelled "ready to paste into the email client": the engineer would have sent the customer
// SOTI's internal case assessment, quoted lines and all.
// The leading "\[?" matters: the heading a model copies out is usually STILL BRACKETED — the
// observed 30/60/90 answer ended with a verbatim "[CASE HISTORY — OLDEST FIRST]" and nine of the
// block's own rows, including the mail confidentiality footer presented to the engineer as a
// case event. Without the bracket this pattern matched neither that heading nor (once the inline
// pass had reworded it) anything else, so the dump survived both guards.
const DIRECTIVE_DUMP_HEAD_RE = /^\s*(?:\*\*|##\s*)?\[?(?:CASE STATE|LOG ACCESS|CHAIN LANGUAGE|DECISIVE CASE SIGNALS|CASE SIGNALS|MCMR RULE|CASE HISTORY|SOTI CHECKS|RECURRENCE|URGENCY|BUSINESS IMPACT|NOT YET VERIFIED|UNVERIFIED|BLOCKED|OPEN QUESTION|PENDING REQUEST|ALREADY PROMISED|A LIVE SESSION HAS ALREADY BEEN OFFERED|HOW THIS CASE DIFFERS|MANDATORY)\b[^\n]{0,120}?(?:\*\*)?\s*(?:[:\]—–]|$)/;
// The proof lines those blocks carry: `- Elena Fischer wrote on 2h ago: "…"`.
const DIRECTIVE_QUOTE_LINE_RE = /^\s*[-*•]?\s*[^\n]{0,80}\b(?:wrote|said)\b[^\n]{0,40}:\s*["“]/;
// The prose BETWEEN a block's heading and its quotes — "The email chain shows NO confirmed
// resolution and NO closure agreement — this case is STILL OPEN." Recognised by the directives'
// own voice rather than by their exact wording, which would break the moment one is reworded:
// these blocks SHOUT their emphasis, and neither a customer email nor a case summary does.
// Matched on this vocabulary alone, so an ordinary product acronym (SOTI, DS.log, MCMR, CPU)
// can never make a real sentence look like scaffold.
const DIRECTIVE_SHOUT_RE = /\b(?:NO|NOT|NEVER|MUST|ONLY|STILL|OPEN|FORBIDDEN|MANDATORY|EXACT|EXACTLY|EVERY|ALWAYS|CRITICAL|VERIFIED|FACT|SAME|AGAIN)\b/;
function stripEchoedDirectiveBlocks(text) {
    const src = String(text || '');
    const lines = src.split('\n');
    const start = lines.findIndex(l => DIRECTIVE_DUMP_HEAD_RE.test(l));
    if (start <= 0) return src;                      // never at index 0 — that would be the answer
    const tail = lines.slice(start).filter(l => l.trim());
    if (!tail.length) return src;
    // Only a genuine DUMP is cut. A single sentence that happens to open with one of these words
    // is left alone: real content mixed into the tail keeps the tail.
    const directiveish = tail.filter(l =>
        DIRECTIVE_DUMP_HEAD_RE.test(l) || DIRECTIVE_QUOTE_LINE_RE.test(l) || /^\s*[-*•]\s/.test(l)
        || DIRECTIVE_SHOUT_RE.test(l)).length;
    if (directiveish / tail.length < 0.7) return src;
    const head = lines.slice(0, start).join('\n').replace(/\s+$/, '');
    return head ? head + '\n' : src;
}

function sanitizeAssistantResponse(text) {
    if (!text) return "";
    
    // Strip thinking/reasoning blocks from models like Gemma 4 e2b/e4b, QwQ, etc.
    // These models may wrap internal reasoning in <think>...</think> or <|think|>...<|/think|> tags.
    // IMPORTANT: only remove WELL-FORMED (closed) blocks. The old version stripped to end-of-string
    // on an unclosed tag, which nuked the entire answer to blank when a model emitted a stray/unclosed
    // <think>. Any leftover lone markers are removed but their inner text is kept.
    let cleaned = text
        .replace(/<think>[\s\S]*?<\/think>/gi, '')
        .replace(/<\|think\|>[\s\S]*?<\|\/?think\|>/gi, '')
        .replace(/<\/?\|?think\|?>/gi, '')
        .trim();

    // ORDER MATTERS. A whole block copied out of the prompt is cut FIRST, while its heading is
    // still the bracketed ALL-CAPS name the dump guard recognises. Running the inline reword
    // first — as this did — rewrote "[CASE HISTORY — OLDEST FIRST]" to "the case history", which
    // then matched nothing, so the guard that exists to delete the dump silently laundered it
    // into what read like real output and kept every row.
    try { cleaned = stripEchoedDirectiveBlocks(cleaned); } catch (e) { console.warn('Directive-dump guard failed', e); }

    // Then the prompt's own scaffolding, out. A step whose object is one of those blocks is
    // deleted; every other reference is reworded into English so the sentence around it
    // survives. Runs on the streaming text too, so the engineer never watches "[MCMR RULE]"
    // appear in an answer they are about to copy into Salesforce.
    try { cleaned = stripPromptScaffold(cleaned); } catch (e) { console.warn('Scaffold leak guard failed', e); }

    // The underscore / no-space spellings of the same labels, which the guard above does not
    // carry (they are not how any prompt writes them, only how a model sometimes echoes them).
    // Fence-aware like everything else here, so a quoted log line is never edited.
    const LABELS = 'MC VERSIONS|AGENT VERSIONS|IDENTITY VERSIONS|RELEASE_NOTES|PULSE_SEARCH|PULSESEARCH|DOCS_SEARCH|DOCSSEARCH|DEEP_RESEARCH|DEEPRESEARCH|CASE_CONTEXT|ISSUE_SUMMARY|ISSUESUMMARY';
    const labelRx = new RegExp(`\\[(?:${LABELS})\\]`, 'gi');
    const accordingRx = new RegExp(`\\b(?:According to|based on)\\s+(?:available information|(?:${labelRx.source}(?:,\\s*|\\s+and\\s+)?)+)\\s*,?\\s*`, 'gi');
    const strayRx = new RegExp(`\\s*${labelRx.source}(?:,\\s*|\\s+and\\s+)?\\s*`, 'gi');
    const refRx = /\b(?:for more (?:detailed )?information|reference|see)\s*,?\s*(?:at\s*)?\[(?:DEEP RESEARCH|DEEP_RESEARCH|DEEPRESEARCH|DOCS SEARCH|DOCS_SEARCH|DOCSSEARCH|PULSE SEARCH|PULSE_SEARCH|PULSESEARCH)\][^\n.]*/gi;

    cleaned = mapProseLines(cleaned, (l) => l
        .replace(accordingRx, "")
        .replace(strayRx, " ")
        .replace(refRx, ""));

    cleaned = cleaned
        .replace(/\bNo specific highlights[^.]*\./gi, "")
        // Remove leftover citation PLACEHOLDERS the model copies from the template instead of
        // real values ("Line N", "Line X", "@ Timestamp T", "(timestamp)", "ExceptionClass").
        // Real citations use digits ("Line 8924") and real dates, so these only match garbage.
        .replace(/\s*@\s*Timestamp(?:\s+[A-Z]\b)?/g, "")     // "@ Timestamp T" / "@ Timestamp"
        .replace(/:?\s*Lines?\s+[A-Z]\b(?:\s*-\s*[A-Z]\b)?/g, "")  // ":Line N" / "Lines X-Y" placeholders
        .replace(/\(\s*timestamp\s*\)/gi, "")
        .replace(/`?\bExceptionClass\b`?/g, "the exception")
        // Strip any "Based on …," preamble at the very START of the answer (the user never wants
        // the response to open with "Based on the provided documentation / the logs / …").
        .replace(/^\s*[Bb]ased (?:on|upon)\b[^,.\n]{0,90}[,:]\s*/, "")
        // Strip source meta-commentary the model sometimes prepends mid-text and the unhelpful
        // "consult/contact support" deflections.
        .replace(/\b[Bb]ased on (?:the )?(?:provided|retrieved|available|the above)[^,.\n]*,?\s*/g, "")
        .replace(/\b(?:the )?(?:retrieved|provided) (?:knowledge base|documentation|context|information)\b/gi, "the SOTI documentation")
        // The wildcards are bounded to a sentence's worth of characters. Unbounded, this pattern
        // rescans the rest of the line from every character position — quadratic, and this runs
        // on every render tick of a streaming answer, so a model stuck repeating one token froze
        // the panel (40 KB of it cost two seconds per tick). No real sentence exceeds 300 chars.
        .replace(/[^.\n]{0,300}\b(?:consult the full SOTI documentation|contact SOTI support|was not (?:explicitly )?detailed in[^.\n]{0,300})\b[^.\n]{0,300}\.?/gi, "")
        // Small-model artifact: a bold pair split across a newline ("**\nKey Details:**")
        // is invalid markdown that would render as literal asterisks — rejoin it.
        .replace(/\*\*\s*\n\s*([^\n*]{1,60}:)\s*\*\*/g, "\n**$1**")
        // Small-model artifact: a version number broken across lines ("2026.1.\n0.") —
        // rejoin so it never renders as a stray numbered-list item.
        .replace(/(\b20\d\d\.\d+\.)\s*\n+\s*(\d)\b/g, "$1$2")
        // A bold section label glued to its text ("**Summary:**The customer") renders and
        // copies without the space — fix it at the source so every consumer (renderer,
        // copy button, export) sees clean text.
        .replace(/(\*\*[^\n*]{1,80}:\*\*)(?=[^\s*])/g, "$1 ")
        .replace(/[ \t]{2,}/g, " ")
        .replace(/\n {1,}/g, "\n")
        .trim();
    return stripEmailChainMarkers(cleaned).replace(/[ \t]{2,}/g, " ").trim();
}

/* ---------------------------------------------------------------------------
 * MEETING NOTES — the headings, and the example that sets the standard
 * ---------------------------------------------------------------------------
 * One definition drives both: the SKELETON that is really pre-filled into the
 * field (so every set of notes arrives structured, and the structure persists
 * into the case record) and the EXAMPLE shown behind it until the engineer
 * starts typing. Deriving both from the same list is what stops the guidance
 * and the headings drifting apart when either is edited.
 * ------------------------------------------------------------------------- */
// Example lines are kept SHORT on purpose. The layer that draws them must not wrap
// (see renderMeetingNotesGhost) or it would fall out of step with the textarea's
// caret, so each line has to fit the panel at its narrowest.
const MEETING_NOTES_SECTIONS = [
    {
        header: 'Summary:',
        example: [
            'Devices dropping offline after the 15.5.1 upgrade.',
            '~40 Android Enterprise devices, since 04/08.'
        ]
    },
    {
        header: 'Troubleshooting steps:',
        example: [
            '- Last successful device check-in 04/08 09:12',
            '- Ruled out network: port 5494 open',
            '- Collected DS + MS logs for the window'
        ]
    },
    {
        header: 'Next steps:',
        example: [
            '- Send re-enrolment steps to customer by 07/08',
            '- Review logs and confirm root cause'
        ]
    }
];

// What the field actually contains on a new case: the headings, with room under each.
const MEETING_NOTES_SKELETON = MEETING_NOTES_SECTIONS
    .map(s => [s.header, ...s.example.map(() => '')].join('\n'))
    .join('\n\n');

// What is shown behind them while the field is untouched.
const MEETING_NOTES_EXAMPLE = MEETING_NOTES_SECTIONS
    .map(s => [s.header, ...s.example].join('\n'))
    .join('\n\n');

// The skeleton earlier versions pre-filled, including the "Time of the meeting:" line that
// is no longer wanted. Saved cases still carry it, so everything that asks "are these notes
// empty?" must keep recognising it.
const MEETING_NOTES_EMPTY_TEMPLATE = 'Time of the meeting:\n\nSummary:\n\nTroubleshooting steps:\n\nNext steps:';

// True when the field holds no actual notes — blank, the current headings-only skeleton,
// or a skeleton left behind by an older build.
function meetingNotesAreEmpty(value) {
    const v = (value || '').trim();
    if (!v) return true;
    if (v === MEETING_NOTES_EMPTY_TEMPLATE) return true;
    if (v === MEETING_NOTES_SKELETON.trim()) return true;
    // Headings with nothing typed under them, whatever the blank-line spacing.
    const stripped = v.split('\n').map(l => l.trim()).filter(Boolean).join('\n');
    const headersOnly = MEETING_NOTES_SECTIONS.map(s => s.header).join('\n');
    return stripped === headersOnly;
}

function getDefaultCI() {
    return {
        caseNum: '', caseStatus: '', caseUrl: '', sotiVer: '', jiraNum: '', platform: '', agentVer: '', caseAge: '',
        enviro: '', dsCfg: '', affDev: '',
        scrubAccount: '', scrubCustomer: '',
        // The headings only — the worked example is shown behind them by the ghost layer
        // until the engineer types, so it never has to be deleted before writing.
        meetingNotes: MEETING_NOTES_SKELETON,
        issueSummary: '', product: '', emailChain: '', jiraDetails: '',
        jiraExpected: '', jiraImpact: '', jiraPriority: 'Medium', jiraRepro: ''
    };
}

function getDefaultCase(name = 'Case 1') {
    return {
        id: 'case-' + (typeof crypto !== 'undefined' && crypto.randomUUID ? crypto.randomUUID() : Date.now() + '-' + Math.floor(Math.random() * 10000)),
        name,
        msgs: [],
        logs: [],
        imgs: [], // { name, data, text }
        ci: getDefaultCI(),
        createdAt: Date.now() // Used for data retention enforcement
    };
}

let _suppressStorageReload = false;
let _saveStateTimer = null;
let _renderTabsTimer = null;
// Deterministic guard against reloading our OWN storage writes. The old 80ms timer was too
// short once a case held megabytes of logs: chrome.storage.local.set took longer than 80ms,
// so the suppress flag cleared before our own onChanged fired, the listener reloaded our
// write, re-rendered (tab flicker, scroll jump) and re-saved — a self-sustaining glitch loop.
// Now every write carries a unique token; the listener ignores any change carrying our token.
let _lastWriteToken = '';
function _newWriteToken() {
    _lastWriteToken = Date.now().toString(36) + Math.random().toString(36).slice(2, 8);
    return _lastWriteToken;
}

// ---- STORAGE FOOTPRINT CONTROL (browser RAM / crash guard) ----
// A log object carries huge DERIVED data in memory: lines[] (a full second copy of the
// text) and precomputedIntel/panelIntel (per-line cache arrays whose shared default
// objects EXPAND into a full object PER LINE when serialized). Passing raw `cases` to
// chrome.storage.local.set made Chrome build a multi-gigabyte serialization payload right
// after an analysis of unzipped log bundles (millions of lines), spiking the browser past
// 7GB and crashing the tab. Storage now only ever receives the raw fields below — the
// derived caches are rebuilt on demand. Log TEXT is persisted under a separate per-case
// key ('caseLogs:<id>') written ONLY when that case's logs actually change, so routine
// saves (every send / field edit) no longer re-serialize megabytes of log text either.
const LOGS_KEY_PREFIX = 'caseLogs:';
const _dirtyLogCases = new Set(); // case ids whose logs changed since the last persist
function markLogsDirty(caseId) { if (caseId) _dirtyLogCases.add(caseId); }

function sanitizeLogForStorage(l, withContent) {
    const out = {
        name: l.name || '',
        sourceZip: l.sourceZip || '',
        uploadedAt: l.uploadedAt || 0,
        size: l.content ? l.content.length : 0
    };
    if (withContent) out.content = l.content || '';
    return out;
}

// View of `cases` safe to hand to storage: logs reduced to raw fields (metadata-only for
// the main state key; inline content only for the small standalone/localStorage fallback).
function sanitizeCasesForStorage(list, inlineLogContent = false) {
    return (list || []).map(c => ({ ...c, logs: (c.logs || []).map(l => sanitizeLogForStorage(l, inlineLogContent)) }));
}

/* ---------------------------------------------------------------------------
 * ON-DEMAND LOG HYDRATION  (the single biggest resident-memory saving)
 * ---------------------------------------------------------------------------
 * Startup used to read the log TEXT of EVERY stored case into memory at once —
 * chrome.storage.local.get(cases.map(...)) — and then keep it all there for the
 * whole session, even though only one case is ever on screen. Five cases with a
 * few unzipped bundles between them meant ~100MB of resident strings before the
 * user had done anything, and every one of those strings later grew a lines[]
 * array (a second full copy) plus per-line intel caches.
 *
 * Log text is now HYDRATED PER CASE. The always-loaded part is metadata (name,
 * size, sourceZip) — enough to render the Logs panel and the file manifest.
 * Content arrives when a case is opened and can be handed back under memory
 * pressure, because it is durable on disk and re-readable at any time.
 *
 * INVARIANT the rest of the file relies on: THE ACTIVE CASE IS ALWAYS HYDRATED.
 * switchCase() and send() both await ensureCaseHydrated(), so every analysis
 * path continues to see log.content exactly as before.
 * ------------------------------------------------------------------------- */
const _hydratedCases = new Set();      // case ids whose log text is resident
const _hydrating = new Map();          // case id -> in-flight hydration promise

function _logsAreHydrated(c) {
    if (!c) return true;
    const logs = c.logs || [];
    if (logs.length === 0) return true;
    // A stub carries a size but no content. If any log still looks like a stub,
    // the case needs a hydration pass.
    return !logs.some(l => l && !l.content && l.size > 0);
}

// Pull one case's log text from its per-case storage key and merge it onto the
// metadata stubs already in memory. Safe to call repeatedly and concurrently.
async function ensureCaseHydrated(caseId) {
    const c = cases.find(x => x.id === caseId);
    if (!c) return false;
    if (_logsAreHydrated(c)) { _hydratedCases.add(caseId); return true; }
    if (_hydrating.has(caseId)) return _hydrating.get(caseId);

    const job = (async () => {
        const t0 = performance.now();
        try {
            if (typeof chrome === 'undefined' || !chrome.storage || !chrome.storage.local) return false;
            const key = LOGS_KEY_PREFIX + caseId;
            const got = await chrome.storage.local.get(key);
            const stored = got[key];
            if (!Array.isArray(stored)) return false;

            // Match stored text back onto the in-memory stubs by name (+ source
            // zip), not by index: a removeLog() between save and hydrate would
            // otherwise attach one file's text to another file's row.
            const byName = new Map();
            stored.forEach(s => byName.set((s.sourceZip || '') + '␀' + (s.name || ''), s));
            (c.logs || []).forEach(l => {
                const s = byName.get((l.sourceZip || '') + '␀' + (l.name || ''));
                if (s && typeof s.content === 'string') {
                    l.content = s.content;
                    l.size = s.content.length;
                }
            });
            _hydratedCases.add(caseId);
            Power.perf.mark('case-hydrate', {
                caseId,
                files: stored.length,
                bytes: stored.reduce((a, s) => a + (s.content ? s.content.length : 0), 0),
                ms: Math.round(performance.now() - t0)
            });
            return true;
        } catch (e) {
            console.warn('[Power] Log hydration failed for', caseId, e);
            return false;
        } finally {
            _hydrating.delete(caseId);
        }
    })();

    _hydrating.set(caseId, job);
    return job;
}

// Hand a case's log text (and everything derived from it) back to the browser.
// Only ever applied to cases that are NOT active and whose text is safely on
// disk — never to unsaved work. Returns the approximate bytes released.
function dehydrateCaseLogs(caseId) {
    const c = cases.find(x => x.id === caseId);
    if (!c || caseId === activeCaseId) return 0;
    // Standalone mode has no per-case storage key to read the text back from, so
    // releasing it there is data loss, not reclaim.
    if (typeof chrome === 'undefined' || !chrome.storage || !chrome.storage.local) return 0;
    // Text not yet flushed to storage would be genuinely lost, so leave it.
    if (_dirtyLogCases.has(caseId)) return 0;

    let freed = 0;
    (c.logs || []).forEach(l => {
        if (!l) return;
        if (typeof l.content === 'string' && l.content.length) {
            l.size = l.content.length;          // keep the panel's size column truthful
            freed += l.content.length * 2;      // JS strings are UTF-16
            l.content = '';
        }
        freed += dropDerivedLogCaches(l);
    });
    _hydratedCases.delete(caseId);
    return freed;
}

// Keep the number of hydrated cases — and the total resident log text — inside
// what the governor says this machine can carry. Cases are released
// least-recently-touched first; the active case is never a candidate.
function trimHydratedCases() {
    const knobs = Power.knobs;
    const candidates = cases
        .filter(c => c.id !== activeCaseId && _hydratedCases.has(c.id))
        .sort((a, b) => (a.updatedAt || a.lastSentAt || a.createdAt || 0) - (b.updatedAt || b.lastSentAt || b.createdAt || 0));

    let residentBytes = 0;
    cases.forEach(c => (c.logs || []).forEach(l => { if (l && l.content) residentBytes += l.content.length * 2; }));

    let freed = 0;
    // 1 for the active case itself — maxHydratedCases counts total, not extras.
    let overflow = candidates.length - Math.max(0, (knobs.maxHydratedCases === Infinity ? Infinity : knobs.maxHydratedCases - 1));
    for (const c of candidates) {
        const overCount = overflow > 0;
        const overBytes = residentBytes > knobs.maxResidentLogBytes;
        if (!overCount && !overBytes) break;
        const got = dehydrateCaseLogs(c.id);
        freed += got;
        residentBytes -= got;
        overflow--;
    }
    if (freed > 0) {
        Power.perf.mark('case-dehydrate', { freedMB: +(freed / 1048576).toFixed(1), reason: 'hydration-budget' });
    }
    return freed;
}

// Drop the DERIVED per-log caches: lines[] (a full second copy of the text) and
// the per-line classification arrays. All of it is pure function of `content`
// and is rebuilt on demand by precomputeLogIntel/getLogPanelIntel, so this is
// the cheapest memory in the app to give back — and the first thing sacrificed.
function dropDerivedLogCaches(l) {
    if (!l) return 0;
    let freed = 0;
    if (Array.isArray(l.lines) && l.lines.length) {
        // Each line is a separate string object; ~ the text again plus per-string
        // overhead. The estimate only feeds the monitor's "reclaimed" figure.
        freed += (l.content ? l.content.length * 2 : l.lines.length * 40);
        l.lines = null;
    }
    if (l.precomputedIntel) {
        const n = (l.precomputedIntel.intelCache || []).length;
        freed += n * 24;   // parallel typed-ish arrays: ~24 bytes/line of slots
        l.precomputedIntel = null;
    }
    if (l._derived) {
        // Memoized evidence sections (exception blocks, installer analysis, …).
        // All rebuildable from the text, so they are always safe to drop.
        l._derived.values.forEach(v => { freed += typeof v === 'string' ? v.length * 2 : 2048; });
        l._derived = null;
    }
    if (l.panelIntel) {
        freed += 4096;
        l.panelIntel = null;
    }
    return freed;
}

function buildCaseCiFromForm() {
    return {
        caseNum: $('caseNum').value,
        caseStatus: $('caseStatus').value,
        caseUrl: $('caseUrl').value,
        sotiVer: $('sotiVer').value,
        jiraNum: $('jiraNum').value,
        platform: $('platform').value,
        agentVer: $('agentVer').value,
        caseAge: $('caseAge').value,
        // Environment / MC Hosted / Affected Devices were edited and validated like every other
        // field but were never written into the case record, so switching tabs silently wiped
        // them — and MC Hosted in particular now drives who collects the logs.
        enviro: $('enviro').value,
        dsCfg: $('dsCfg').value,
        affDev: $('affDev').value,
        scrubAccount: $('scrubAccount').value,
        scrubCustomer: $('scrubCustomer').value,
        meetingNotes: $('meetingNotes').value,
        issueSummary: $('issueSummary').value,
        product: $('product').value,
        emailChain: $('emailChain').value,
        jiraDetails: $('jiraDetails').value,
        jiraExpected: $('jiraExpected').value,
        jiraImpact: $('jiraImpact').value,
        jiraPriority: $('jiraPriority').value,
        jiraRepro: $('jiraRepro').value
    };
}

function syncActiveCaseCiFromForm() {
    if (!activeCaseId) return false;
    const idx = cases.findIndex(c => c.id === activeCaseId);
    if (idx === -1) return false;
    cases[idx].ci = buildCaseCiFromForm();
    return true;
}

function scheduleSaveState(delayMs = 450) {
    if (_saveStateTimer) clearTimeout(_saveStateTimer);
    const caseIdAtSchedule = activeCaseId;
    _saveStateTimer = setTimeout(() => {
        _saveStateTimer = null;
        if (!caseIdAtSchedule || activeCaseId !== caseIdAtSchedule) return;
        saveState();
    }, delayMs);
}

function scheduleRenderTabs(delayMs = 280) {
    if (_renderTabsTimer) clearTimeout(_renderTabsTimer);
    _renderTabsTimer = setTimeout(() => {
        _renderTabsTimer = null;
        renderTabs();
    }, delayMs);
}

async function saveState() {
    if (!activeCaseId) return;
    try {
        if (!syncActiveCaseCiFromForm()) return;

        // Stamp the active case as "touched now" so the 30-day inactivity retention clock
        // resets whenever the user works on it (saveState runs on edits, attaches, sends).
        const _activeCase = cases.find(x => x.id === activeCaseId);
        if (_activeCase) _activeCase.updatedAt = Date.now();

        // Write a lightweight quick-cache to sessionStorage for instant UI on next open.
        // This is synchronous and extremely fast — it only stores tab names and the last 20 msgs.
        try {
            const quickCache = {
                activeCaseId,
                cases: cases.map(c => ({
                    id: c.id,
                    name: c.name,
                    createdAt: c.createdAt,
                    ci: c.ci,
                    logs: (c.logs || []).map(l => ({ name: l.name, size: l.content ? l.content.length : 0 })),
                    msgs: (c.msgs || []).filter(m => !m.hidden).slice(-20)
                }))
            };
            sessionStorage.setItem('soti_ai_quick_cache', JSON.stringify(quickCache));
        } catch (e) { /* sessionStorage may be unavailable in some contexts */ }

        _suppressStorageReload = true;
        if (typeof chrome !== 'undefined' && chrome.storage && chrome.storage.local) {
            const payload = { cases: sanitizeCasesForStorage(cases), activeCaseId, _stateWriteToken: _newWriteToken() };
            // Log text is persisted per-case and only when that case's logs changed
            // (attach/remove) — one atomic set() so state and text never drift apart.
            for (const cid of _dirtyLogCases) {
                const dc = cases.find(x => x.id === cid);
                if (dc) payload[LOGS_KEY_PREFIX + cid] = (dc.logs || []).map(l => sanitizeLogForStorage(l, true));
            }
            await chrome.storage.local.set(payload);
            _dirtyLogCases.clear(); // only after a successful write — a failed one retries next save
        } else {
            localStorage.setItem('soti_ai_state', JSON.stringify({ cases: sanitizeCasesForStorage(cases, true), activeCaseId }));
        }
    } catch (e) {
        console.error('CRITICAL: Save failed', e);
        if (e.message.includes('quota')) {
            toast('Storage quota exceeded! Clear old cases.', 'e');
        } else {
            toast('Failed to save session state', 'e');
        }
    } finally {
        setTimeout(() => { _suppressStorageReload = false; }, 80);
    }
}

async function loadState() {
    // --- PHASE 1: INSTANT RENDER from sessionStorage quick-cache (synchronous, zero delay) ---
    // Paint the UI immediately so the user sees their cases the moment the extension opens.
    try {
        const raw = sessionStorage.getItem('soti_ai_quick_cache');
        if (raw) {
            const quick = JSON.parse(raw);
            if (quick.cases && quick.cases.length > 0) {
                // Inflate minimal case objects enough to render tabs and chat history
                cases = quick.cases.map(c => ({
                    ...c,
                    logs: [],  // log content not cached (too large) — restored in phase 2
                    imgs: []
                }));
                activeCaseId = null;
                renderTabs();
                switchCase(quick.activeCaseId || cases[0].id);
            }
        }
    } catch (e) { /* ignore quick-cache errors, full load below will fix everything */ }

    // --- PHASE 2: FULL LOAD from chrome.storage (async, replaces quick render if needed) ---
    try {
        let data = {};
        if (typeof chrome !== 'undefined' && chrome.storage && chrome.storage.local) {
            data = await chrome.storage.local.get(['cases', 'activeCaseId', 'msgs', 'ci', 'logs', 'cachedVersions']);
        } else {
            // Fallback to localStorage if chrome API is missing (standalone mode)
            const local = localStorage.getItem('soti_ai_state');
            if (local) data = JSON.parse(local);
            const cached = localStorage.getItem('soti_ai_cached_versions');
            if (cached) data.cachedVersions = JSON.parse(cached);
        }
        
        // Populate cached versions immediately on startup to avoid race conditions
        if (data.cachedVersions) {
            VERSIONS = data.cachedVersions.VERSIONS || [];
            AGENT_VERSIONS = data.cachedVersions.AGENT_VERSIONS || [];
            IDENTITY_VERSIONS = data.cachedVersions.IDENTITY_VERSIONS || [];
            updateVersionDropdowns();
        }
        
        // Migration logic for old single-session data
        if (data.msgs && !data.cases) {
            const oldCase = {
                id: 'case-' + (typeof crypto !== 'undefined' && crypto.randomUUID ? crypto.randomUUID() : Date.now() + '-' + Math.floor(Math.random() * 10000)),
                name: 'Case 1',
                msgs: data.msgs || [],
                logs: data.logs || [],
                ci: data.ci || {}
            };
            cases = [oldCase];
            activeCaseId = oldCase.id;
        } if (data.cases && data.cases.length > 0) {
            cases = data.cases;

            const targetId = data.activeCaseId || cases[0].id;

            // ---- LOG TEXT: METADATA NOW, CONTENT ON DEMAND ----
            // Previously every case's log text was read here in one
            // chrome.storage.local.get(all keys) and kept resident for the whole
            // session. That is what made the panel start at ~100MB with nothing
            // open. Now only the case being OPENED is hydrated; the rest stay as
            // metadata stubs (name/size/sourceZip) until switchCase() opens them.
            //
            // LEGACY states stored full log objects inline in the main key —
            // content plus lines[]/panelIntel/precomputedIntel caches. Those are
            // still migrated to their per-case key on sight, because leaving them
            // inline means re-serializing megabytes on every routine save.
            // Lazy hydration is only SAFE where the text can be read back. In
            // standalone mode there is no chrome.storage — log text lives inline in
            // the localStorage state — so stubbing it out there would simply delete
            // it. Standalone therefore keeps the old eager behaviour; the extension,
            // which is where the big multi-case sessions actually happen, gets the
            // lazy path.
            const canRehydrate = typeof chrome !== 'undefined' && !!(chrome.storage && chrome.storage.local);
            const migrateLegacy = {};
            const stubLog = l => ({
                name: l.name || '',
                content: '',
                size: typeof l.size === 'number' ? l.size : (l.content ? l.content.length : 0),
                sourceZip: l.sourceZip || '',
                uploadedAt: l.uploadedAt || 0
            });
            const keepLog = l => ({
                name: l.name || '',
                content: l.content || '',
                size: l.content ? l.content.length : (l.size || 0),
                sourceZip: l.sourceZip || '',
                uploadedAt: l.uploadedAt || 0
            });
            cases.forEach(c => {
                const inline = Array.isArray(c.logs) ? c.logs : [];
                const withText = inline.filter(l => l && typeof l.content === 'string' && l.content);
                if (!canRehydrate) {
                    // Standalone: whatever text we have is the only copy — keep it.
                    c.logs = (withText.length ? withText : inline).map(keepLog);
                    if (withText.length) _hydratedCases.add(c.id);
                    return;
                }
                if (withText.length) {
                    // LEGACY inline state: move the text to its per-case key so routine
                    // saves stop re-serializing it, then drop to a stub like everyone else.
                    migrateLegacy[LOGS_KEY_PREFIX + c.id] = withText.map(l => sanitizeLogForStorage(l, true));
                    c.logs = withText.map(stubLog);
                } else {
                    c.logs = inline.map(stubLog);
                }
            });
            if (Object.keys(migrateLegacy).length > 0 && typeof chrome !== 'undefined' && chrome.storage && chrome.storage.local) {
                chrome.storage.local.set({ ...migrateLegacy, _stateWriteToken: _newWriteToken() }).catch(e => console.warn('Legacy log migration write failed', e));
            }
            _hydratedCases.clear();

            // Hydrate ONLY the case about to be shown. switchCase() below re-checks
            // and awaits this, so nothing downstream can observe a half-loaded case.
            if (cases.find(c => c.id === targetId)) {
                try { await ensureCaseHydrated(targetId); } catch (e) { /* stubs still render */ }
            }
            
            // Patch existing cases for missing properties
            cases.forEach(c => {
                // Migration: cases saved by earlier versions carry the old pre-filled
                // skeleton (including the "Time of the meeting:" line). Clear it so the
                // placeholder example shows through — but ONLY when it is still the
                // untouched skeleton, never when the engineer has written into it.
                if (c.ci && meetingNotesAreEmpty(c.ci.meetingNotes)) {
                    c.ci.meetingNotes = MEETING_NOTES_SKELETON;
                }
                if (!c.imgs) c.imgs = [];
                if (!c.createdAt) c.createdAt = Date.now(); // Backfill for older cases
                // Migration: older versions stored full log dumps inside chat messages,
                // which crowded newly added logs out of the model's context. Strip them.
                if (Array.isArray(c.msgs)) {
                    c.msgs.forEach(m => {
                        if (m && typeof m.content === 'string' && m.content.includes('=== FILE:')) {
                            m.content = m.content.replace(/=== FILE:[\s\S]*?=== END[^\n]*\n?/g, '[log snippet removed — logs are attached to the case]\n');
                        }
                    });
                }
            });

            // DATA RETENTION: auto-purge cases (and their stored logs) after 30 days of
            // INACTIVITY. Sensitive customer logs shouldn't sit on disk longer than needed.
            // Keyed on last activity (updatedAt/lastSentAt), not creation time, so a case you
            // keep working on survives and only genuinely idle cases are cleared.
            const RETENTION_MS = 30 * 24 * 60 * 60 * 1000; // 30 days of inactivity
            const now = Date.now();
            const before = cases.length;
            const lastTouch = c => c.updatedAt || c.lastSentAt || c.createdAt || now;
            const purgedCases = cases.filter(c => (now - lastTouch(c)) >= RETENTION_MS);
            cases = cases.filter(c => (now - lastTouch(c)) < RETENTION_MS);
            const purged = before - cases.length;
            if (purged > 0) {
                console.warn(`[Security] Data retention: purged ${purged} case(s) idle for over 30 days.`);
                toast(`${purged} idle case(s) auto-cleared (30-day retention policy)`, 'w', 5000);
                if (typeof chrome !== 'undefined' && chrome.storage && chrome.storage.local) {
                    chrome.storage.local.set({ cases: sanitizeCasesForStorage(cases), _stateWriteToken: _newWriteToken() });
                    // Purge the per-case log text too — that's the actual customer data.
                    chrome.storage.local.remove(purgedCases.map(c => LOGS_KEY_PREFIX + c.id)).catch(() => {});
                }
            }

            // If all cases were purged, create a fresh default
            if (cases.length === 0) {
                const newCase = getDefaultCase('Case 1');
                cases = [newCase];
                activeCaseId = null; // Force re-render
                renderTabs();
                switchCase(newCase.id);
                return;
            }

            const safeTargetId = cases.find(c => c.id === targetId) ? targetId : cases[0].id;
            renderTabs();
            activeCaseId = null; // Force re-render and avoid saving stale DOM state
            switchCase(safeTargetId);
            return;
        } 
        
        // If we reach here, we need a default case
        const newCase = getDefaultCase('Case 1');
        cases = [newCase];
        activeCaseId = null; // Force re-render
        saveState();

        renderTabs();
        switchCase(newCase.id);
    } catch (e) { 
        console.warn('Load failed', e);
        // Absolute fallback if everything fails
        if (cases.length === 0) {
            const id = 'case-fallback';
            cases = [{ id, name: 'Case 1', msgs: [], logs: [], ci: getDefaultCI() }];
            activeCaseId = id;
            renderTabs();
            switchCase(id);
        }
    }
}

function createNewCase() {
    // Cancel any pending renderTabs timer
    if (_renderTabsTimer) { clearTimeout(_renderTabsTimer); _renderTabsTimer = null; }
    // Find the highest number in existing case names to determine next name
    let nextNum = cases.length + 1;
    const names = cases.map(c => c.name);
    while (names.includes(`Case ${nextNum}`)) {
        nextNum++;
    }
    const name = `Case ${nextNum}`;
    const newCase = getDefaultCase(name);
    cases.push(newCase);
    renderTabs();
    switchCase(newCase.id);
}

let _switching = false; // true while switchCase is executing — blocks field handlers

function switchCase(id) {
    if (!id || !cases.find(x => x.id === id)) {
        if (cases.length > 0 && cases[0].id !== id) switchCase(cases[0].id);
        return;
    }

    // If already fully rendered on this tab, just ensure highlight is correct
    if (activeCaseId === id) {
        document.querySelectorAll('.tab-item').forEach(t =>
            t.classList.toggle('active', t.dataset.id === id)
        );
        return;
    }

    // Reentrance guard — if we're already mid-switch, just update the target
    if (_switching) return;
    _switching = true;

    // Cancel all pending timers — we're doing a definitive switch right now
    if (_saveStateTimer) { clearTimeout(_saveStateTimer); _saveStateTimer = null; }
    if (_renderTabsTimer) { clearTimeout(_renderTabsTimer); _renderTabsTimer = null; }

    try {
        const c = cases.find(x => x.id === id);
        if (!c) { _switching = false; return; }

        // Snapshot the OLD case's form values before overwriting the DOM
        if (activeCaseId) syncActiveCaseCiFromForm();
        activeCaseId = id;

        // Update UI Fields
        $('caseNum').value = c.ci.caseNum || '';
        $('caseUrl').value = c.ci.caseUrl || '';
        // Through the helper, not a bare .value: a case stored with a status outside the
        // picklist would otherwise restore blank, because a fresh DOM has no such option.
        applyCaseStatus(c.ci.caseStatus);
        $('sotiVer').value = c.ci.sotiVer || '';
        $('jiraNum').value = c.ci.jiraNum || '';
        $('platform').value = c.ci.platform || '';
        $('agentVer').value = c.ci.agentVer || '';
        $('caseAge').value = c.ci.caseAge || '';
        $('enviro').value = c.ci.enviro || '';
        $('dsCfg').value = c.ci.dsCfg || '';
        $('affDev').value = c.ci.affDev || '';
        $('scrubAccount').value = c.ci.scrubAccount || '';
        $('scrubCustomer').value = c.ci.scrubCustomer || '';
        $('meetingNotes').value = c.ci.meetingNotes || MEETING_NOTES_SKELETON;
        renderMeetingNotesGhost();
        $('issueSummary').value = c.ci.issueSummary || '';
        $('product').value = c.ci.product || '';
        $('emailChain').value = c.ci.emailChain || '';
        $('jiraDetails').value = c.ci.jiraDetails || '';
        $('jiraExpected').value = c.ci.jiraExpected || '';
        $('jiraImpact').value = c.ci.jiraImpact || '';
        $('jiraPriority').value = c.ci.jiraPriority || 'Medium';
        $('jiraRepro').value = c.ci.jiraRepro || '';

        // Rebuild the version dropdowns for the restored product (e.g. so MobiControl shows
        // "2026.0.0" while XSight shows "2026.0"). Setting .value above doesn't fire the
        // product 'onchange', and updateVersionDropdowns() rebuilds the <option> lists, so
        // re-apply the saved version selections afterward.
        updateVersionDropdowns();
        $('sotiVer').value = c.ci.sotiVer || '';
        $('agentVer').value = c.ci.agentVer || '';

        // Re-render Chat
        const chat = $('chatMsgs');
        if (chat) {
            chat.querySelectorAll('.msg').forEach(m => m.remove());

            if (c.msgs.length === 0) {
                if ($('welcome')) $('welcome').style.display = 'flex';
            } else {
                if ($('welcome')) $('welcome').style.display = 'none';
                const frag = document.createDocumentFragment();
                c.msgs.forEach(m => {
                    if (m.hidden) return;
                    const w = document.createElement('div'); w.className = `msg ${m.role}`;
                    const b = document.createElement('div'); b.className = 'mb'; b.innerHTML = md(m.content);
                    w.appendChild(b);
                    // Re-attach Copy + 👍/👎 so quick-action answers keep their copy button and
                    // rated answers keep their confirmation across tab switches.
                    if (m.role === 'assistant') { attachCopyUI(b, m); attachFeedbackUI(b, c, m); }
                    frag.appendChild(w);
                });
                chat.appendChild(frag);

                // Re-attach any live streaming element for this case
                const liveAib = streamingElements.get(id);
                if (liveAib) {
                    const liveWrapper = document.createElement('div');
                    liveWrapper.className = 'msg assistant';
                    liveWrapper.appendChild(liveAib);
                    chat.appendChild(liveWrapper);
                }

                chat.scrollTop = chat.scrollHeight;
            }
        }

        renderImgs();
        renderLogs();
        updateAllValidations();
        updateQuickActionsPanel();
        // The Send button belongs to the tab now on screen, not to whatever ran last.
        syncSendEnabled();

        // Update tab highlight
        document.querySelectorAll('.tab-item').forEach(t =>
            t.classList.toggle('active', t.dataset.id === id)
        );

        // Bring this case's log TEXT back into memory (it may be a metadata-only
        // stub after startup or after a reclaim), and let go of the cases that are
        // now over the governor's hydration budget. Deliberately NOT awaited — the
        // panel is already painted from metadata and stays interactive while the
        // read completes. Every consumer of log.content (send(), Analyse Now) awaits
        // ensureCaseHydrated() itself, so nothing can race ahead of this.
        ensureCaseHydrated(id).then(hydrated => {
            if (hydrated && activeCaseId === id) renderLogs();
            trimHydratedCases();
        }).catch(() => {});

        // Deferred storage write — token-tagged so our own onChanged is ignored (no reload loop)
        _suppressStorageReload = true;
        requestAnimationFrame(() => {
            if (typeof chrome !== 'undefined' && chrome.storage && chrome.storage.local) {
                chrome.storage.local.set({ cases: sanitizeCasesForStorage(cases), activeCaseId, _stateWriteToken: _newWriteToken() }).catch(e =>
                    console.error('SwitchCase save failed', e)
                ).finally(() => {
                    setTimeout(() => { _suppressStorageReload = false; }, 80);
                });
            } else {
                try { localStorage.setItem('soti_ai_state', JSON.stringify({ cases: sanitizeCasesForStorage(cases, true), activeCaseId })); } catch(e) {}
                setTimeout(() => { _suppressStorageReload = false; }, 80);
            }
        });
    } finally {
        _switching = false;
    }
}

function closeCase(id, e) {
    if (e) e.stopPropagation();
    const removeStoredLogs = caseId => {
        if (typeof chrome !== 'undefined' && chrome.storage && chrome.storage.local) {
            chrome.storage.local.remove(LOGS_KEY_PREFIX + caseId).catch(() => {});
        }
    };
    // Releasing a case is the one moment we can hand back everything it held, so
    // do it explicitly rather than leaving it to whenever the collector notices.
    const releaseLogs = caseObj => {
        (caseObj && caseObj.logs || []).forEach(l => { if (l) { dropDerivedLogCaches(l); l.content = ''; } });
        if (caseObj) _hydratedCases.delete(caseObj.id);
    };
    if (cases.length <= 1) {
        const c = cases[0];
        releaseLogs(c);
        c.name = 'Case 1';
        c.msgs = [];
        c.logs = [];
        c.ci = getDefaultCI();
        removeStoredLogs(c.id); // the stored log text is the actual customer data — delete it now
        // Force switchCase to run even if it's already active to refresh the UI
        const oldId = activeCaseId;
        activeCaseId = null;
        switchCase(oldId || c.id);
        renderTabs();
        return;
    }

    const idx = cases.findIndex(c => c.id === id);
    if (idx === -1) return;

    const wasActive = (activeCaseId === id);
    releaseLogs(cases[idx]);
    cases.splice(idx, 1);
    removeStoredLogs(id);
    _dirtyLogCases.delete(id);
    
    if (wasActive) {
        const nextId = cases[Math.max(0, idx - 1)].id;
        switchCase(nextId);
    }
    renderTabs();
    saveState();
}

function renderTabs() {
    const bar = $('tabBar');
    if (!bar) return;
    const scrollLeft = bar.scrollLeft;

    // --- Smart in-place patch ---
    // Build a map of existing tab elements by case ID so we can reuse them.
    // This avoids destroying DOM nodes mid-click, which was causing the glitch.
    const existingMap = new Map();
    bar.querySelectorAll('.tab-item').forEach(el => {
        existingMap.set(el.dataset.id, el);
    });

    const usedIds = new Set();

    // Two tabs opened on the SAME case number rendered as two identical "Case C01745392"
    // labels with nothing to tell them apart — and since each tab holds its own chat, logs
    // and analysis, picking the wrong one silently puts the work in the wrong place. Number
    // the duplicates in tab order so they stay distinguishable.
    const numCounts = new Map();
    cases.forEach(c => {
        const n = (c.ci.caseNum || '').trim();
        if (n) numCounts.set(n, (numCounts.get(n) || 0) + 1);
    });
    const numSeen = new Map();

    cases.forEach((c, i) => {
        const caseNum = (c.ci.caseNum || '').trim();
        let label = caseNum ? `Case ${caseNum}` : c.name;
        if (caseNum && numCounts.get(caseNum) > 1) {
            const nth = (numSeen.get(caseNum) || 0) + 1;
            numSeen.set(caseNum, nth);
            label += ` (${nth})`;
        }
        let t = existingMap.get(c.id);

        if (!t) {
            // Brand-new tab — create the element
            t = document.createElement('div');
            t.dataset.id = c.id;
            t.draggable = true;

            const name = document.createElement('span');
            name.className = 'tab-name';
            t.appendChild(name);

            const close = document.createElement('div');
            close.className = 'tab-close';
            close.textContent = '×';
            close.onclick = (e) => closeCase(c.id, e);
            t.appendChild(close);

            // Wire click on the tab itself (not the close button)
            t.onclick = (e) => {
                if (e.target.classList.contains('tab-close')) return;
                switchCase(c.id);
            };
            t.ondragstart = (e) => {
                e.dataTransfer.setData('text/plain', i);
                t.classList.add('dragging');
            };
            t.ondragend = () => t.classList.remove('dragging');
            t.ondragover = (e) => e.preventDefault();
            t.ondrop = (e) => {
                e.preventDefault();
                const fromIdx = parseInt(e.dataTransfer.getData('text/plain'));
                const toIdx = cases.findIndex(x => x.id === c.id);
                if (fromIdx === toIdx || fromIdx < 0 || toIdx < 0) return;
                const [moved] = cases.splice(fromIdx, 1);
                cases.splice(toIdx, 0, moved);
                renderTabs();
                saveState();
            };
        }

        // Always update class and label (cheap — no DOM destruction)
        t.className = `tab-item${c.id === activeCaseId ? ' active' : ''}`;
        t.querySelector('.tab-name').textContent = label;
        usedIds.add(c.id);

        // Ensure correct order: append moves it to the right position
        bar.appendChild(t);
    });

    // Remove tabs for cases that no longer exist
    existingMap.forEach((el, id) => {
        if (!usedIds.has(id)) bar.removeChild(el);
    });

    bar.scrollLeft = scrollLeft;
}




