            const byLength = Math.min(filled.length / expectedGenLen, 0.98);
            const frac = Math.min(Math.max(byMarkers, byLength), 0.99);
            const writing = genMarkerIdx > 0 ? JIRA_GEN_MARKERS[genMarkerIdx - 1].label : '';
